let cw, ch
let nodesToSplit
let rootNode
let animFrames = 50
let restFrames = 120
let animFrame = 0
let restFrame = 0
let state = 'anim'
let sep
let partitionRange = [0.3, 0.7]
let heightRange = [0, 100]

let palettes = [
  ["#ed225d", "#3caf65", "#0d40bf", "#f5b800", "#2a2a2a"],
  ["#b30000", "#e6cf00", "#1283b3", "#fafafa", "#0a0a0a"],
  ["#f24358", "#f2a643", "#f2e343", "#43f278", "#43a0f2", "#c343f2"],
  ["#606c38", "#283618", "#fefae0", "#dda15e", "#bc6c25"],
  ["#001427", "#708d81", "#f4d58d", "#bf0603", "#8d0801"],
  ["#3d5a80", "#98c1d9", "#e0fbfc", "#ee6c4d", "#293241"],
  ["#4464a1", "#62b6de", "#b3dce0", "#fafafa", "#ffc5c7", "#ee726b", "#cd1440"],
  ["#353535", "#3c6e71", "#ffffff", "#d9d9d9", "#284b63"],
  ["#0081a7", "#00afb9", "#fdfcdc", "#fed9b7", "#f07167"],
  ["#004b23", "#006400", "#007200", "#008000", "#38b000", "#70e000", "#9ef01a", "#ccff33"],
  ["#0a1128", "#001f54", "#034078", "#1282a2", "#fefcfb"],
  ["#2d3142", "#bfc0c0", "#ffffff", "#ef8354", "#4f5d75"],
  ["#04151f", "#183a37", "#efd6ac", "#c44900", "#432534"],
  ["#ca9ce1", "#54defd", "#f1ffc4", "#ffcaaf", "#28587b"],
]
let palette, bgColor

function setup() {
  createCanvas(windowWidth, windowHeight)
  cw = windowWidth
  ch = windowHeight
  palette = random(palettes)
  bgColor = random(palette)
  setupTree()
}

function draw () {
  background(bgColor + '60')
  if (state === 'anim') {
    rootNode.retarget(easeInOutQuint(animFrame / animFrames))
    animFrame++
    if (animFrame >= animFrames) {
      background(bgColor)
      state = 'rest'
      animFrame = 0
      restFrame = 0
    }
  } else {
    rootNode.clearTarget()
    restFrame++
    if (restFrame >= restFrames) {
      state = 'anim'
      restFrame = 0
      animFrame = 0
    }
  }
  rootNode.draw()
}

function mouseClicked () {
  setupTree()
}

function setupTree () {
  sep = random(10, 20)
  nodesToSplit = []
  rootNode = new Node(sep * 2, sep * 2, cw - 4 * sep, ch - 4 * sep, randomColor(), {
    minSize: 100
  })
  nodesToSplit.push(
    ...rootNode.split(
      random(...partitionRange),
      random(["horizontal", "vertical"]),
      randomColor(),
      randomColor()
    )
  )
  let splits = floor(random(15, 100))
  for (let i = 0; i < splits; i++) {
    _splitTree()
  }
}

function _splitTree() {
  let numTries = 100
  let nodeToSplit = random(nodesToSplit)
  let children = nodeToSplit.split(
    random(...partitionRange),
    random(["horizontal", "vertical"]),
    randomColor(),
    randomColor()
  )
  while (children.length === 0 && numTries > 0) {
    children = nodeToSplit.split(
      random(...partitionRange),
      random(["horizontal", "vertical"]),
      randomColor(),
      randomColor()
    )
    numTries--
  }
  if (children.length > 0) {
    nodesToSplit.splice(nodesToSplit.indexOf(nodeToSplit), 1)
    nodesToSplit.push(...children)
  }
}

class Node {
  constructor(x, y, w, h, color = null, config = {}) {
    this.x = x
    this.y = y
    this.width = w
    this.height = h
    this.color = color
    this.children = []
    this.config = config
    this.minSize = config.minSize || 50
    this.h = random(...heightRange)
    this.direction = random(["horizontal", "vertical"])
    this.lineSep = this.direction === "horizontal" ? this.height / random(50, 100) : this.width  / random(50, 100)
    this.lineSep = constrain(this.lineSep, 5, 40)
    this.lineWeight = this.lineSep * random(0.05, 0.5)
    this.dx = random(-0.2, 0.2)
    this.dy = random(-0.2, 0.2)
  }

  split(p = 0.5, direction = "horizontal", c1, c2) {
    let child1, child2
    this.partition = p
    this.direction = direction
    if (this.direction === "horizontal") {
      const splitHeight = this.height * p
      if (splitHeight < this.minSize || this.height - splitHeight < this.minSize) {
        return []
      }
      child1 = new Node(this.x, this.y, this.width, splitHeight, this.color)
      child2 = new Node(
        this.x,
        this.y + splitHeight,
        this.width,
        this.height - splitHeight,
        c2
      )
    } else if (this.direction === "vertical") {
      const splitWidth = this.width * p
      if (splitWidth < this.minSize || this.width - splitWidth < this.minSize) {
        return []
      }
      child1 = new Node(this.x, this.y, splitWidth, this.height, this.color)
      child2 = new Node(
        this.x + splitWidth,
        this.y,
        this.width - splitWidth,
        this.height,
        c2
      )
    }
    this.children.push(child1, child2)
    return [child1, child2]
  }

  draw () {
    if (this.children.length === 0) {
      this.tColor ||= randomColor()

      push()
      translate(this.x + this.width / 2, this.y + this.height / 2)

      fill(this.tColor)
      rectMode(CENTER)
      this.drawRect()
      pop()

    }
    this.children.forEach((child) => child.draw())
  }

  drawRect () {
    stroke(this.tColor)
    strokeWeight(this.lineWeight)
    strokeCap(SQUARE)
    push()
    translate(this.width * this.dx, this.height * this.dy)
    if (this.direction === "horizontal") {
      let y = -this.height / 2
      while (y < this.height / 2) {
        let h = this.h
        line(-this.width / 2, y + h / 2, this.width / 2, y + h / 2)
        y += this.lineSep
      }
    } else {
      let x = -this.width / 2
      while (x < this.width / 2) {
        let w = this.h
        line(x + w / 2, -this.height / 2, x + w / 2, this.height / 2)
        x += this.lineSep
      }
    }
    pop()
  }

  recalculate (p = null) {
    // Change the partition of this node then recalculate the children
    if (p === null) {
      p = this.source || random(...partitionRange)
    }
    if (this.children.length === 0) {
      return
    }
    this.partition = p
    if (this.direction === "horizontal") {
      const splitHeight = this.height * p
      this.children[0].x = this.x
      this.children[0].y = this.y
      this.children[0].width = this.width
      this.children[0].height = splitHeight
      this.children[1].x = this.x
      this.children[1].y = this.y + splitHeight
      this.children[1].height = this.height - splitHeight
      this.children[1].width = this.width
    } else if (this.direction === "vertical") {
      const splitWidth = this.width * p
      this.children[0].x = this.x
      this.children[0].y = this.y
      this.children[0].width = splitWidth
      this.children[0].height = this.height
      this.children[1].x = this.x + splitWidth
      this.children[1].y = this.y
      this.children[1].width = this.width - splitWidth
      this.children[1].height = this.height
    }
    this.children.forEach((child) => child.recalculate())
    // Reassign lineSep and lineWeight
    this.lineSep = this.direction === "horizontal" ? this.height / random(50, 100) : this.width  / random(50, 100)
    this.lineSep = constrain(this.lineSep, 5, 40)
    this.lineWeight = this.lineSep * random(0.05, 0.5)
  }

  retarget (progress) {
    if (!this.target) {
      this.source = this.partition || 0.5
      this.target = random(...partitionRange)
      this.hSource = this.h || random(...heightRange)
      this.hTarget = random(...heightRange)
    }
    this.h = lerp(this.hSource, this.hTarget, progress)
    this.recalculate(lerp(this.source, this.target, progress))
    this.children.forEach((child) => child.retarget(progress))
  }

  clearTarget () {
    this.source = this.partition
    this.target = null
    this.hSource = this.h
    this.hTarget = null
    this.children.forEach((child) => child.clearTarget())
  }
}

let randomColor = () => {
  return random(palette)
}

function easeInOutQuint(x) {
  return x < 0.5 ? 16 * x * x * x * x * x : 1 - pow(-2 * x + 2, 5) / 2
}

function getComplementaryColor (c) {
  let hsv = chroma(c).hsv()
  let hue = hsv[0]

  let complementaryHue = (hue + 180) % 360
  let splitComp1 = (complementaryHue + 30) % 360
  let splitComp2 = (complementaryHue - 30 + 360) % 360 // Adding 360 to avoid negative values

  let splitCompColor1 = chroma.hsv(splitComp1, hsv[1], hsv[2]).hex()
  let splitCompColor2 = chroma.hsv(splitComp2, hsv[1], hsv[2]).hex()

  return random([splitCompColor1, splitCompColor2])
}

// On click, pick a new palette and regenerate the tree
function mouseClicked () {
  palette = random(palettes)
  bgColor = random(palette)
  setupTree()
}
